// Compiles data/schemas/*.schema.json into dependency-free validator code (Ajv standalone).
// Run: node scripts/compile-schemas.mjs        (writes the generated file)
//      node scripts/compile-schemas.mjs --check (fails if the generated file is stale)
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv from "ajv";
import standaloneCode from "ajv/dist/standalone/index.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "packages", "core");
const out = join(root, "src", "einvoice", "validators.generated.ts");

export function generate() {
  const load = (f) => JSON.parse(readFileSync(join(root, "data", "schemas", f), "utf8"));
  // unicode: false keeps maxLength checks free of Ajv runtime imports.
  const ajv = new Ajv({
    code: { source: true, esm: true },
    allErrors: true,
    unicode: false,
    strict: true,
  });
  ajv.addKeyword("x-source").addKeyword("x-last-verified").addKeyword("x-verification");
  ajv.addSchema(load("einvoice-1.1.schema.json"), "einvoice");
  ajv.addSchema(load("ewaybill-bulk.schema.json"), "ewaybill");
  const code = standaloneCode(ajv, { einvoice: "einvoice", ewaybill: "ewaybill" });
  if (/require\(|from "ajv/.test(code))
    throw new Error("Generated validator must not import Ajv at runtime.");
  return `// @ts-nocheck\n/* eslint-disable */\n// GENERATED by scripts/compile-schemas.mjs from data/schemas. Do not edit.\n${code}\n`;
}

const code = generate();
if (process.argv.includes("--check")) {
  if (readFileSync(out, "utf8") !== code) {
    console.error("validators.generated.ts is stale. Run: node scripts/compile-schemas.mjs");
    process.exit(1);
  }
  console.log("validators.generated.ts is up to date");
} else {
  writeFileSync(out, code);
  console.log("wrote", out);
}
